import { DEFAULT_TESTID_ATTR, TESTID_ATTR_PATTERN } from '@reticlehq/core';
let testIdAttr = DEFAULT_TESTID_ATTR;
export function getTestIdAttr() {
    return testIdAttr;
}
export function testIdSelector() {
    return `[${testIdAttr}]`;
}
export function readTestId(el) {
    return el.getAttribute(testIdAttr);
}
export function setTestIdAttr(name) {
    testIdAttr = undefined !== name && TESTID_ATTR_PATTERN.test(name) ? name : DEFAULT_TESTID_ATTR;
}
