import { UNREACHABLE_NOTICE_PREFIX } from '@reticlehq/core';
export function unreachableMessage(url, attempts) {
    return (`${UNREACHABLE_NOTICE_PREFIX}${url}. ${String(attempts)} attempts, all ` +
        `failed. That is everything the page can see: from inside the browser it cannot tell a daemon ` +
        `that is not there from one it is not allowed to reach, so this is not evidence about the ` +
        `daemon. What answers it: run \`npx @reticlehq/server status\` to see whether one is listening ` +
        `and on which port. If your app runs in a container, devcontainer or WSL, the daemon is on a ` +
        `different host, so point the page at it: RETICLE_PORT or reticle({ port }) with the Vite ` +
        `plugin, reticle.connect({ url }) by hand. An https page cannot open a ws:// socket. Still retrying…`);
}
export const UNREACHABLE_HEADLINE = "Can't reach Reticle from this page. Run reticle status to check, or reticle serve to start it.";
