import { getTestIdAttr, testIdSelector } from '../dom/addressing/testid-attr.js';
export const MAX_AUTO_TESTIDS = 200;
const RETICLE_OWN_PREFIX = 'reticle-';
export function domTestids(doc) {
    const out = [];
    const seen = new Set();
    let nodes;
    try {
        nodes = doc.querySelectorAll(testIdSelector());
    }
    catch {
        return out;
    }
    for (let i = 0; i < nodes.length && out.length < MAX_AUTO_TESTIDS; i += 1) {
        const value = nodes[i]?.getAttribute(getTestIdAttr());
        if (null === value || undefined === value)
            continue;
        const trimmed = value.trim();
        if (0 === trimmed.length || seen.has(trimmed))
            continue;
        if (trimmed.startsWith(RETICLE_OWN_PREFIX))
            continue;
        seen.add(trimmed);
        out.push(trimmed);
    }
    return out;
}
